insert into tours (slug, data, sort_order) values ('catamaran-isla-mujeres', '{"slug": "catamaran-isla-mujeres", "name": {"es": "Catamar\u00e1n a Isla Mujeres", "en": "Isla Mujeres Catamaran"}, "category": "acuatico", "tagline": {"es": "Vela, snorkel y playa en un solo d\u00eda", "en": "Sailing, snorkeling, and beach in one day"}, "description": {"es": "Zarpe desde Canc\u00fan en un catamar\u00e1n de cubierta abierta. Snorkel en el arrecife, open bar tropical y tiempo libre en Playa Norte, una de las bah\u00edas m\u00e1s calmadas del Caribe. Gu\u00eda biling\u00fce y toallas a bordo.", "en": "Set sail from Canc\u00fan on an open-deck catamaran. Snorkel the reef, tropical open bar, and free time on Playa Norte, one of the calmest bays in the Caribbean. Bilingual guide and towels on board."}, "duration": {"es": "7 horas", "en": "7 hours"}, "location": {"es": "Canc\u00fan \u00b7 Isla Mujeres", "en": "Canc\u00fan \u00b7 Isla Mujeres"}, "meeting": {"es": "Recogida en hotel zona hotelera y downtown", "en": "Hotel pickup in the hotel zone and downtown"}, "meetingQuery": "Marina El Embarcadero, Canc\u00fan, M\u00e9xico", "stops": [{"name": {"es": "Salida \u2014 Marina El Embarcadero", "en": "Departure \u2014 Marina El Embarcadero"}, "description": {"es": "Abordaje y briefing de seguridad antes de zarpar.", "en": "Boarding and safety briefing before setting sail."}}, {"name": {"es": "Snorkel \u2014 arrecife El Meco", "en": "Snorkel \u2014 El Meco reef"}, "description": {"es": "Primera parada de snorkel sobre coral y peces tropicales.", "en": "First snorkel stop over coral and tropical fish."}}, {"name": {"es": "Playa Norte, Isla Mujeres", "en": "Playa Norte, Isla Mujeres"}, "description": {"es": "Tiempo libre en la playa, open bar y buffet a bordo.", "en": "Free time on the beach, open bar and buffet on board."}}], "private": {"pricePerPerson": 120, "unitCapacity": 10, "minGuaranteePeople": 6, "minGuaranteeAmount": 720, "underfillSurchargePct": 0.25, "minAdvanceDays": 3}, "includes": [{"es": "Traslado ida y vuelta desde el hotel", "en": "Round-trip hotel transfer"}, {"es": "Snorkel con equipo", "en": "Snorkeling with gear"}, {"es": "Open bar nacional", "en": "Domestic open bar"}, {"es": "Buffet ligero a bordo", "en": "Light buffet on board"}, {"es": "Tiempo libre en Playa Norte", "en": "Free time on Playa Norte"}], "notIncluded": [{"es": "Propinas", "en": "Tips"}, {"es": "Fotos profesionales", "en": "Professional photos"}, {"es": "Impuesto de muelle (aprox. $12 USD)", "en": "Pier tax (approx. $12 USD)"}], "highlights": [{"es": "Arrecife El Meco", "en": "El Meco reef"}, {"es": "Playa Norte", "en": "Playa Norte"}, {"es": "Barra libre", "en": "Open bar"}], "price": 89, "originalPrice": 129, "rating": 4.8, "reviewCount": 1842, "image": "/images/catamaran-isla.jpg", "lastMinute": {"seats": 6, "discountPct": 31, "departs": "hoy"}, "groupSize": {"es": "Hasta 40", "en": "Up to 40"}, "languages": {"es": "Espa\u00f1ol e ingl\u00e9s", "en": "Spanish and English"}}'::jsonb, 0)
  on conflict (slug) do nothing;
insert into tours (slug, data, sort_order) values ('snorkel-arrecife-cancun', '{"slug": "snorkel-arrecife-cancun", "name": {"es": "Snorkel en el arrecife de Canc\u00fan", "en": "Canc\u00fan Reef Snorkeling"}, "category": "acuatico", "tagline": {"es": "Parque Marino Nacional, agua cristalina", "en": "National Marine Park, crystal-clear water"}, "description": {"es": "Salida temprana hacia el Parque Marino. Dos paradas de snorkel sobre coral de cerebro y abanicos, con pez \u00e1ngel, loro y a veces rayas. Grupos reducidos y briefing de conservaci\u00f3n.", "en": "Early departure to the Marine Park. Two snorkel stops over brain coral and sea fans, with angelfish, parrotfish, and sometimes rays. Small groups and a conservation briefing."}, "duration": {"es": "4 horas", "en": "4 hours"}, "location": {"es": "Punta Nizuc \u00b7 Canc\u00fan", "en": "Punta Nizuc \u00b7 Canc\u00fan"}, "meeting": {"es": "Muelle Punta Nizuc, traslado opcional", "en": "Punta Nizuc pier, optional transfer"}, "meetingQuery": "Punta Nizuc, Canc\u00fan, M\u00e9xico", "stops": [{"name": {"es": "Salida \u2014 Muelle Punta Nizuc", "en": "Departure \u2014 Punta Nizuc pier"}, "description": {"es": "Equipo de snorkel y briefing.", "en": "Snorkel gear and briefing."}}, {"name": {"es": "Primer sitio de arrecife", "en": "First reef site"}, "description": {"es": "Coral de cerebro y abanicos, poca profundidad.", "en": "Brain coral and sea fans, shallow depth."}}, {"name": {"es": "Segundo sitio de arrecife", "en": "Second reef site"}, "description": {"es": "Zona con m\u00e1s vida marina, peces \u00e1ngel y loro.", "en": "Area with more marine life, angelfish and parrotfish."}}], "private": {"pricePerPerson": 75, "unitCapacity": 8, "minGuaranteePeople": 4, "minGuaranteeAmount": 300, "underfillSurchargePct": 0.25, "minAdvanceDays": 2}, "includes": [{"es": "Lancha exclusiva de grupo peque\u00f1o", "en": "Exclusive small-group boat"}, {"es": "Equipo de snorkel y chaleco", "en": "Snorkel gear and life vest"}, {"es": "Gu\u00eda certificado", "en": "Certified guide"}, {"es": "Agua y fruta", "en": "Water and fruit"}, {"es": "Seguro de viajero", "en": "Traveler insurance"}], "notIncluded": [{"es": "Fotos", "en": "Photos"}, {"es": "Propinas", "en": "Tips"}, {"es": "Parque marino si aplica", "en": "Marine park fee if applicable"}], "highlights": [{"es": "Dos arrecifes", "en": "Two reefs"}, {"es": "Grupo peque\u00f1o", "en": "Small group"}, {"es": "Salida matutina", "en": "Morning departure"}], "price": 59, "rating": 4.7, "reviewCount": 963, "image": "/images/snorkel-arrecife.jpg", "groupSize": {"es": "Hasta 12", "en": "Up to 12"}, "languages": {"es": "Espa\u00f1ol e ingl\u00e9s", "en": "Spanish and English"}}'::jsonb, 1)
  on conflict (slug) do nothing;
insert into tours (slug, data, sort_order) values ('tiburon-ballena', '{"slug": "tiburon-ballena", "name": {"es": "Nado con tibur\u00f3n ballena", "en": "Whale Shark Swim"}, "category": "acuatico", "tagline": {"es": "El pez m\u00e1s grande del planeta, a tu lado", "en": "The largest fish on the planet, right beside you"}, "description": {"es": "Temporada de junio a septiembre. Navegaci\u00f3n hacia Isla Contoy / Isla Mujeres para nadar junto a tiburones ballena en su ruta de alimentaci\u00f3n. Solo se permite un n\u00famero limitado de nadadores por animal.", "en": "Season runs June to September. Sail out toward Isla Contoy / Isla Mujeres to swim alongside whale sharks on their feeding route. Only a limited number of swimmers are allowed per animal."}, "duration": {"es": "8 horas", "en": "8 hours"}, "location": {"es": "Isla Mujeres \u00b7 mar abierto", "en": "Isla Mujeres \u00b7 open sea"}, "meeting": {"es": "Recogida en hotel 6:30\u20137:00", "en": "Hotel pickup 6:30\u20137:00 AM"}, "meetingQuery": "Puerto Ju\u00e1rez, Canc\u00fan, M\u00e9xico", "stops": [{"name": {"es": "Salida \u2014 Puerto Ju\u00e1rez", "en": "Departure \u2014 Puerto Ju\u00e1rez"}, "description": {"es": "Abordaje y navegaci\u00f3n hacia la zona de avistamiento.", "en": "Boarding and sail out toward the sighting zone."}}, {"name": {"es": "Nado con tibur\u00f3n ballena", "en": "Whale shark swim"}, "description": {"es": "Grupos peque\u00f1os en el agua, turnos regulados por permiso.", "en": "Small groups in the water, permit-regulated turns."}}, {"name": {"es": "Isla Contoy / Isla Mujeres", "en": "Isla Contoy / Isla Mujeres"}, "description": {"es": "Parada de descanso y almuerzo antes de regresar.", "en": "Rest and lunch stop before heading back."}}], "private": {"pricePerPerson": 195, "unitCapacity": 8, "minGuaranteePeople": 6, "minGuaranteeAmount": 1170, "underfillSurchargePct": 0.25, "minAdvanceDays": 5}, "includes": [{"es": "Traslado hotel", "en": "Hotel transfer"}, {"es": "Desayuno ligero y almuerzo", "en": "Light breakfast and lunch"}, {"es": "Equipo de snorkel", "en": "Snorkel gear"}, {"es": "Permiso de avistamiento", "en": "Sighting permit"}, {"es": "Gu\u00eda marino", "en": "Marine guide"}], "notIncluded": [{"es": "Propinas", "en": "Tips"}, {"es": "Toalla personal", "en": "Personal towel"}], "highlights": [{"es": "Encuentro silvestre", "en": "Wildlife encounter"}, {"es": "Isla Contoy", "en": "Isla Contoy"}, {"es": "Grupo regulado", "en": "Regulated group size"}], "price": 159, "originalPrice": 189, "rating": 4.9, "reviewCount": 721, "image": "/images/tiburon-ballena.jpg", "groupSize": {"es": "Hasta 18", "en": "Up to 18"}, "languages": {"es": "Espa\u00f1ol e ingl\u00e9s", "en": "Spanish and English"}}'::jsonb, 2)
  on conflict (slug) do nothing;
insert into tours (slug, data, sort_order) values ('cenotes-sagrados', '{"slug": "cenotes-sagrados", "name": {"es": "Cenotes sagrados", "en": "Sacred Cenotes"}, "category": "acuatico", "tagline": {"es": "Agua esmeralda bajo la selva maya", "en": "Emerald water beneath the Maya jungle"}, "description": {"es": "Tres cenotes de la riviera: uno abierto, uno semi-abierto y una caverna con estalactitas. Casco, chaleco y gu\u00eda espele\u00f3logo. Ideal si quieres agua dulce y sombra lejos de la playa.", "en": "Three cenotes of the riviera: one open-air, one semi-open, and a cave with stalactites. Helmet, vest, and a caving guide included. Ideal if you want fresh water and shade away from the beach."}, "duration": {"es": "6 horas", "en": "6 hours"}, "location": {"es": "Ruta de los Cenotes \u00b7 Puerto Morelos", "en": "Cenotes Route \u00b7 Puerto Morelos"}, "meeting": {"es": "Recogida en hotel Canc\u00fan o Playa del Carmen", "en": "Hotel pickup in Canc\u00fan or Playa del Carmen"}, "meetingQuery": "Ruta de los Cenotes, Puerto Morelos, M\u00e9xico", "stops": [{"name": {"es": "Cenote abierto", "en": "Open-air cenote"}, "description": {"es": "Primer nado, agua fresca y luz natural.", "en": "First swim, fresh water and natural light."}}, {"name": {"es": "Cenote semi-abierto", "en": "Semi-open cenote"}, "description": {"es": "Formaciones rocosas parcialmente cubiertas.", "en": "Rock formations partially covered."}}, {"name": {"es": "Caverna con estalactitas", "en": "Stalactite cave"}, "description": {"es": "El m\u00e1s dram\u00e1tico de los tres, con casco y gu\u00eda espele\u00f3logo.", "en": "The most dramatic of the three, with helmet and caving guide."}}], "private": {"pricePerPerson": 99, "unitCapacity": 10, "minGuaranteePeople": 5, "minGuaranteeAmount": 495, "underfillSurchargePct": 0.25, "minAdvanceDays": 3}, "includes": [{"es": "Traslado", "en": "Transfer"}, {"es": "Entrada a tres cenotes", "en": "Entry to three cenotes"}, {"es": "Equipo de snorkel y casco", "en": "Snorkel gear and helmet"}, {"es": "Almuerzo regional", "en": "Regional lunch"}, {"es": "Regaderas y lockers", "en": "Showers and lockers"}], "notIncluded": [{"es": "Fotos", "en": "Photos"}, {"es": "Propinas", "en": "Tips"}], "highlights": [{"es": "Caverna iluminada", "en": "Lit cave"}, {"es": "Almuerzo maya", "en": "Maya lunch"}, {"es": "Poca gente", "en": "Few crowds"}], "price": 79, "rating": 4.8, "reviewCount": 1104, "image": "/images/cenotes.jpg", "groupSize": {"es": "Hasta 16", "en": "Up to 16"}, "languages": {"es": "Espa\u00f1ol, ingl\u00e9s y franc\u00e9s", "en": "Spanish, English, and French"}}'::jsonb, 3)
  on conflict (slug) do nothing;
insert into tours (slug, data, sort_order) values ('cozumel-palancar', '{"slug": "cozumel-palancar", "name": {"es": "Cozumel: arrecife Palancar", "en": "Cozumel: Palancar Reef"}, "category": "acuatico", "tagline": {"es": "El arrecife m\u00e1s claro del Caribe mexicano", "en": "The clearest reef in the Mexican Caribbean"}, "description": {"es": "Ferry a Cozumel y dos inmersiones de snorkel o bautizo de buceo en Palancar Gardens. Corriente suave, visibilidad de 30 metros y pared de coral. Incluye almuerzo en la isla.", "en": "Ferry to Cozumel and two snorkel dives or a discovery dive at Palancar Gardens. Gentle current, 30 meters of visibility, and a coral wall. Includes lunch on the island."}, "duration": {"es": "9 horas", "en": "9 hours"}, "location": {"es": "Cozumel", "en": "Cozumel"}, "meeting": {"es": "Ferry Playa del Carmen, traslado desde Canc\u00fan", "en": "Playa del Carmen ferry, transfer from Canc\u00fan"}, "meetingQuery": "Muelle Fiscal, Playa del Carmen, M\u00e9xico", "stops": [{"name": {"es": "Salida \u2014 Muelle Fiscal", "en": "Departure \u2014 Muelle Fiscal"}, "description": {"es": "Ferry a Cozumel, ~45 minutos.", "en": "Ferry to Cozumel, ~45 minutes."}}, {"name": {"es": "Palancar Gardens", "en": "Palancar Gardens"}, "description": {"es": "Dos inmersiones de snorkel o bautizo de buceo.", "en": "Two snorkel dives or a discovery scuba dive."}}, {"name": {"es": "Almuerzo en Cozumel", "en": "Lunch in Cozumel"}, "description": {"es": "Tiempo libre en el muelle antes del regreso.", "en": "Free time at the pier before heading back."}}], "private": {"pricePerPerson": 159, "unitCapacity": 10, "minGuaranteePeople": 6, "minGuaranteeAmount": 954, "underfillSurchargePct": 0.25, "minAdvanceDays": 4}, "includes": [{"es": "Traslado Canc\u00fan\u2013Playa", "en": "Canc\u00fan\u2013Playa transfer"}, {"es": "Ferry ida y vuelta", "en": "Round-trip ferry"}, {"es": "Dos sitios de arrecife", "en": "Two reef sites"}, {"es": "Equipo completo", "en": "Full gear"}, {"es": "Almuerzo en muelle", "en": "Lunch at the pier"}], "notIncluded": [{"es": "Propinas de tripulaci\u00f3n", "en": "Crew tips"}, {"es": "Nitrox", "en": "Nitrox"}], "highlights": [{"es": "Visibilidad extrema", "en": "Extreme visibility"}, {"es": "Palancar", "en": "Palancar"}, {"es": "D\u00eda completo", "en": "Full day"}], "price": 129, "rating": 4.8, "reviewCount": 588, "image": "/images/cozumel.jpg", "groupSize": {"es": "Hasta 20", "en": "Up to 20"}, "languages": {"es": "Espa\u00f1ol e ingl\u00e9s", "en": "Spanish and English"}}'::jsonb, 4)
  on conflict (slug) do nothing;
insert into tours (slug, data, sort_order) values ('chichen-itza-amanecer', '{"slug": "chichen-itza-amanecer", "name": {"es": "Chich\u00e9n Itz\u00e1 al amanecer", "en": "Chich\u00e9n Itz\u00e1 at Sunrise"}, "category": "arqueologico", "tagline": {"es": "El Castillo sin filas, con luz dorada", "en": "El Castillo with no lines, in golden light"}, "description": {"es": "Salida de madrugada para entrar con el primer grupo. Recorrido de 2 horas con arque\u00f3logo: El Castillo, el Juego de Pelota, el Observatorio y el Cenote Sagrado. Almuerzo yucateco y parada en cenote para nadar de regreso.", "en": "Pre-dawn departure to enter with the first group. A 2-hour tour with an archaeologist: El Castillo, the Ball Court, the Observatory, and the Sacred Cenote. Yucatecan lunch and a cenote swim stop on the way back."}, "duration": {"es": "12 horas", "en": "12 hours"}, "location": {"es": "Chich\u00e9n Itz\u00e1 \u00b7 Yucat\u00e1n", "en": "Chich\u00e9n Itz\u00e1 \u00b7 Yucat\u00e1n"}, "meeting": {"es": "Recogida 5:30\u20136:00 en hotel", "en": "Hotel pickup 5:30\u20136:00 AM"}, "meetingQuery": "Zona Arqueol\u00f3gica de Chich\u00e9n Itz\u00e1, Yucat\u00e1n, M\u00e9xico", "stops": [{"name": {"es": "El Castillo", "en": "El Castillo"}, "description": {"es": "La pir\u00e1mide principal, con el primer grupo del d\u00eda.", "en": "The main pyramid, with the first group of the day."}}, {"name": {"es": "Juego de Pelota", "en": "The Ball Court"}, "description": {"es": "El campo de juego de pelota m\u00e1s grande de Mesoam\u00e9rica.", "en": "The largest ball court in Mesoamerica."}}, {"name": {"es": "El Observatorio y Cenote Sagrado", "en": "The Observatory and Sacred Cenote"}, "description": {"es": "Recorrido con arque\u00f3logo por el resto del sitio.", "en": "Tour of the rest of the site with an archaeologist."}}, {"name": {"es": "Cenote de regreso", "en": "Cenote on the way back"}, "description": {"es": "Parada para nadar antes de volver al hotel.", "en": "A swim stop before heading back to the hotel."}}], "private": {"pricePerPerson": 129, "unitCapacity": 8, "minGuaranteePeople": 8, "minGuaranteeAmount": 1032, "underfillSurchargePct": 0.25, "minAdvanceDays": 5}, "includes": [{"es": "Traslado en van climatizada", "en": "Air-conditioned van transfer"}, {"es": "Entrada a la zona arqueol\u00f3gica", "en": "Archaeological site entry"}, {"es": "Gu\u00eda arque\u00f3logo certificado", "en": "Certified archaeologist guide"}, {"es": "Almuerzo buffet", "en": "Buffet lunch"}, {"es": "Parada en cenote", "en": "Cenote stop"}], "notIncluded": [{"es": "Propinas", "en": "Tips"}, {"es": "Video oficial INAH", "en": "Official INAH video"}, {"es": "Souvenirs", "en": "Souvenirs"}], "highlights": [{"es": "Acceso temprano", "en": "Early access"}, {"es": "Gu\u00eda arque\u00f3logo", "en": "Archaeologist guide"}, {"es": "Cenote de regreso", "en": "Cenote on the way back"}], "price": 99, "originalPrice": 139, "rating": 4.9, "reviewCount": 2310, "image": "/images/chichen-itza.jpg", "lastMinute": {"seats": 4, "discountPct": 29, "departs": "hoy"}, "groupSize": {"es": "Hasta 14", "en": "Up to 14"}, "languages": {"es": "Espa\u00f1ol e ingl\u00e9s", "en": "Spanish and English"}}'::jsonb, 5)
  on conflict (slug) do nothing;
insert into tours (slug, data, sort_order) values ('tulum-playa', '{"slug": "tulum-playa", "name": {"es": "Tulum ruinas y playa", "en": "Tulum Ruins and Beach"}, "category": "arqueologico", "tagline": {"es": "Templo sobre el acantilado, luego el mar", "en": "A temple on the cliff, then the sea"}, "description": {"es": "Recorrido por la zona amurallada de Tulum con historiador: El Castillo, el Templo de los Frescos y vistas al Caribe. Despu\u00e9s, tiempo libre en la playa de arena blanca bajo las ruinas. Grupos de ma\u00f1ana para evitar el calor pico.", "en": "A tour of Tulum''s walled city with a historian: El Castillo, the Temple of the Frescoes, and Caribbean views. Afterward, free time on the white-sand beach beneath the ruins. Morning groups to avoid peak heat."}, "duration": {"es": "7 horas", "en": "7 hours"}, "location": {"es": "Tulum", "en": "Tulum"}, "meeting": {"es": "Recogida en hotel Canc\u00fan / Riviera Maya", "en": "Hotel pickup in Canc\u00fan / Riviera Maya"}, "meetingQuery": "Zona Arqueol\u00f3gica de Tulum, Quintana Roo, M\u00e9xico", "stops": [{"name": {"es": "El Castillo de Tulum", "en": "El Castillo de Tulum"}, "description": {"es": "El templo principal sobre el acantilado.", "en": "The main temple on the cliff."}}, {"name": {"es": "Templo de los Frescos", "en": "Temple of the Frescoes"}, "description": {"es": "Murallas con pinturas mayas originales.", "en": "Walls with original Maya paintings."}}, {"name": {"es": "Playa bajo las ruinas", "en": "Beach beneath the ruins"}, "description": {"es": "Tiempo libre en la playa de arena blanca.", "en": "Free time on the white-sand beach."}}], "private": {"pricePerPerson": 89, "unitCapacity": 6, "minGuaranteePeople": 6, "minGuaranteeAmount": 534, "underfillSurchargePct": 0.25, "minAdvanceDays": 3}, "includes": [{"es": "Traslado", "en": "Transfer"}, {"es": "Entrada a ruinas", "en": "Ruins entry"}, {"es": "Gu\u00eda historiador", "en": "Historian guide"}, {"es": "Tiempo de playa", "en": "Beach time"}, {"es": "Agua y refrigerio", "en": "Water and a snack"}], "notIncluded": [{"es": "Almuerzo", "en": "Lunch"}, {"es": "Sombrilla de playa", "en": "Beach umbrella"}, {"es": "Propinas", "en": "Tips"}], "highlights": [{"es": "Acantilado Caribe", "en": "Caribbean cliff"}, {"es": "Playa privada del sitio", "en": "The site''s private beach"}, {"es": "Grupo matutino", "en": "Morning group"}], "price": 69, "rating": 4.7, "reviewCount": 1566, "image": "/images/tulum.jpg", "groupSize": {"es": "Hasta 18", "en": "Up to 18"}, "languages": {"es": "Espa\u00f1ol e ingl\u00e9s", "en": "Spanish and English"}}'::jsonb, 6)
