insert into tours (slug, data, sort_order) values ('coba-selva', '{"slug": "coba-selva", "name": {"es": "Cob\u00e1 y selva", "en": "Cob\u00e1 and Jungle"}, "category": "arqueologico", "tagline": {"es": "Pir\u00e1mide en la selva y lagunas mayas", "en": "A jungle pyramid and Maya lagoons"}, "description": {"es": "Cob\u00e1 se recorre en bici entre sacb\u00e9s (calzadas blancas). Subida opcional a Nohoch Mul, la pir\u00e1mide m\u00e1s alta de Quintana Roo. Despu\u00e9s, almuerzo en pueblo maya y nado en un cenote de caverna.", "en": "Cob\u00e1 is explored by bike along sacb\u00e9s (white causeways). Optional climb up Nohoch Mul, the tallest pyramid in Quintana Roo. Afterward, lunch in a Maya village and a swim in a cave cenote."}, "duration": {"es": "10 horas", "en": "10 hours"}, "location": {"es": "Cob\u00e1 \u00b7 Quintana Roo", "en": "Cob\u00e1 \u00b7 Quintana Roo"}, "meeting": {"es": "Recogida en hotel", "en": "Hotel pickup"}, "meetingQuery": "Zona Arqueol\u00f3gica de Cob\u00e1, Quintana Roo, M\u00e9xico", "stops": [{"name": {"es": "Entrada y renta de bici", "en": "Entrance and bike rental"}, "description": {"es": "Recorrido por los sacb\u00e9s (calzadas blancas).", "en": "Ride along the sacb\u00e9s (white causeways)."}}, {"name": {"es": "Nohoch Mul", "en": "Nohoch Mul"}, "description": {"es": "La pir\u00e1mide m\u00e1s alta de Quintana Roo, subida opcional.", "en": "The tallest pyramid in Quintana Roo, optional climb."}}, {"name": {"es": "Cenote y pueblo maya", "en": "Cenote and Maya village"}, "description": {"es": "Almuerzo regional y nado en cenote de caverna.", "en": "Regional lunch and a swim in a cave cenote."}}], "private": {"pricePerPerson": 115, "unitCapacity": 6, "minGuaranteePeople": 6, "minGuaranteeAmount": 690, "underfillSurchargePct": 0.25, "minAdvanceDays": 4}, "includes": [{"es": "Traslado", "en": "Transfer"}, {"es": "Bicicleta en el sitio", "en": "Bike at the site"}, {"es": "Entrada a Cob\u00e1", "en": "Cob\u00e1 entry"}, {"es": "Gu\u00eda local